**What this code covers**

- MCP SDK Example 2: File System Server Demonstrates: Tools + Resources together Uses: mcp==1.9.0
- Expose files as readable resources
- Read a specific file resource
- RESOURCES — Read-only data exposure
- TOOLS — Actions that modify state

**Defines:** `list_resources()`, `read_resource()`, `list_tools()`, `call_tool()`, `main()`

```python name=mcp_sdk_example2_filesystem_server.py
"""
MCP SDK Example 2: File System Server
Demonstrates: Tools + Resources together
Uses: mcp==1.9.0
"""

import asyncio
import os
from pathlib import Path
from mcp.server import Server
from mcp.server.stdio import stdio_server
from mcp.types import (
    Tool, Resource, TextContent,
    CallToolResult, ListToolsResult,
    ListResourcesResult, ReadResourceResult,
    ResourceContents, TextResourceContents,
)

server = Server("filesystem-server")
BASE_DIR = Path("./workspace")  # Sandboxed directory

# ─────────────────────────────────────────────
# RESOURCES — Read-only data exposure
# ─────────────────────────────────────────────
@server.list_resources()
async def list_resources() -> ListResourcesResult:
    """Expose files as readable resources"""
    resources = []
    if BASE_DIR.exists():
        for file_path in BASE_DIR.iterdir():
            if file_path.is_file():
                resources.append(
                    Resource(
                        uri=f"file://{file_path.name}",
                        name=file_path.name,
                        description=f"File: {file_path.name}",
                        mimeType="text/plain",
                    )
                )
    return ListResourcesResult(resources=resources)

@server.read_resource()
async def read_resource(uri: str) -> ReadResourceResult:
    """Read a specific file resource"""
    filename = uri.replace("file://", "")
    file_path = BASE_DIR / filename

    if not file_path.exists():
        raise FileNotFoundError(f"File {filename} not found")

    content = file_path.read_text()
    return ReadResourceResult(
        contents=[
            TextResourceContents(
                uri=uri,
                mimeType="text/plain",
                text=content,
            )
        ]
    )

# ─────────────────────────────────────────────
# TOOLS — Actions that modify state
# ─────────────────────────────────────────────
@server.list_tools()
async def list_tools() -> ListToolsResult:
    return ListToolsResult(
        tools=[
            Tool(
                name="create_file",
                description="Create a new file with content",
                inputSchema={
                    "type": "object",
                    "properties": {
                        "filename": {"type": "string"},
                        "content": {"type": "string"},
                    },
                    "required": ["filename", "content"],
                },
            ),
            Tool(
                name="list_files",
                description="List all files in workspace",
                inputSchema={"type": "object", "properties": {}},
            ),
            Tool(
                name="delete_file",
                description="Delete a file from workspace",
                inputSchema={
                    "type": "object",
                    "properties": {
                        "filename": {"type": "string"},
                    },
                    "required": ["filename"],
                },
            ),
            Tool(
                name="search_in_file",
                description="Search for text within a file",
                inputSchema={
                    "type": "object",
                    "properties": {
                        "filename": {"type": "string"},
                        "query": {"type": "string"},
                    },
                    "required": ["filename", "query"],
                },
            ),
        ]
    )

@server.call_tool()
async def call_tool(name: str, arguments: dict) -> CallToolResult:
    BASE_DIR.mkdir(exist_ok=True)

    if name == "create_file":
        file_path = BASE_DIR / arguments["filename"]
        file_path.write_text(arguments["content"])
        return CallToolResult(
            content=[TextContent(
                type="text",
                text=f"✅ Created file: {arguments['filename']} ({len(arguments['content'])} chars)"
            )]
        )

    elif name == "list_files":
        files = [f.name for f in BASE_DIR.iterdir() if f.is_file()]
        if not files:
            return CallToolResult(
                content=[TextContent(type="text", text="📁 No files in workspace")]
            )
        file_list = "\n".join(f"  📄 {f}" for f in files)
        return CallToolResult(
            content=[TextContent(type="text", text=f"📁 Files in workspace:\n{file_list}")]
        )

    elif name == "delete_file":
        file_path = BASE_DIR / arguments["filename"]
        if file_path.exists():
            file_path.unlink()
            return CallToolResult(
                content=[TextContent(type="text", text=f"🗑️ Deleted: {arguments['filename']}")]
            )
        return CallToolResult(
            content=[TextContent(type="text", text=f"❌ File not found: {arguments['filename']}")],
            isError=True,
        )

    elif name == "search_in_file":
        file_path = BASE_DIR / arguments["filename"]
        if not file_path.exists():
            return CallToolResult(
                content=[TextContent(type="text", text="❌ File not found")],
                isError=True,
            )
        content = file_path.read_text()
        query = arguments["query"].lower()
        lines_found = [
            f"Line {i+1}: {line.strip()}"
            for i, line in enumerate(content.split("\n"))
            if query in line.lower()
        ]
        if lines_found:
            return CallToolResult(
                content=[TextContent(
                    type="text",
                    text=f"🔍 Found '{arguments['query']}' in {len(lines_found)} lines:\n" +
                         "\n".join(lines_found)
                )]
            )
        return CallToolResult(
            content=[TextContent(type="text", text=f"🔍 '{arguments['query']}' not found")]
        )

    raise ValueError(f"Unknown tool: {name}")

async def main():
    async with stdio_server() as streams:
        await server.run(
            streams[0], streams[1],
            server.create_initialization_options(),
        )

if __name__ == "__main__":
    asyncio.run(main())
```

# 🔷 SECTION B: MCP with FastMCP Framework

> **FastMCP** is a high-level Python framework that makes building MCP servers dramatically simpler using decorators — similar to how FastAPI works for REST APIs.
